    (
      (
        DATEDIFF(DAY, CAST('1900-01-01' AS DATE), dt.d1) % 7
      ) + 7
    ) % 7
  ) + 1 AS [dt___v]
FROM dt AS dt
GROUP BY
  dt.id,
  (
    (
      (
        DATEDIFF(DAY, CAST('1900-01-01' AS DATE), dt.d1) % 7
      ) + 7
    ) % 7
  ) + 1

