SELECT
  dt.id AS "dt.id",
  CAST(STRFTIME(
    '%Y',
    DATE(
      dt.d1,
      (
        3 - (
          (
            CAST(STRFTIME('%w', dt.d1) AS INTEGER) + 6
          ) % 7
        )
      ) || ' days'
    )
  ) AS INTEGER) AS "dt.v"
FROM dt AS dt
GROUP BY
  dt.id,
  CAST(STRFTIME(
    '%Y',
    DATE(
      dt.d1,
      (
        3 - (
          (
            CAST(STRFTIME('%w', dt.d1) AS INTEGER) + 6
          ) % 7
        )
      ) || ' days'
    )
  ) AS INTEGER)

